// D9 E3 unit E3-U1: the A04 corpus generator for `a04-corpus/v1`, implementing
// docs/plans/d9-e3-b4-precision-contract.md section 5 as made executable by the section 13
// annex (sections 13.2 to 13.7). It is test-only, deterministic and seeded. It imports nothing
// at runtime but `node:crypto`, and it never loads a kernel, a port or a renderer: no kernel runs
// on this corpus before the freeze (section 5.5).
//
// Floating-point discipline (E3-N9, E3-N10): generation uses only binary64 basic operations
// (+, -, *, /), `Math.floor`, `Math.round` on exact values, and exact BigInt arithmetic. No
// `Math.sin`, `Math.cos`, `Math.sqrt` or `Math.pow` is evaluated here. Every irrational-derived
// constant (T1, T2, T6, the chevron arms, f01, f06, f08, j05 and the AL-OB5 rings) is a hex
// literal; tests/geometry/e3-a04-corpus.test.ts re-derives each with exact BigInt arithmetic.
//
// Any change to this file is a new corpus version (section 5.1, E3-Q4): the manifest records
// this file's SHA-256 and the regeneration test fails on any difference.

import { createHash } from 'node:crypto';

export const A04_CORPUS_VERSION = 'a04-corpus/v1';

// ---------------------------------------------------------------------------------------------
// Binary64 helpers

const VIEW = new DataView(new ArrayBuffer(8));

/** The 16-digit lower-case hex bit pattern of a binary64 value. */
export function hex(value: number): string {
  VIEW.setFloat64(0, value);
  return VIEW.getBigUint64(0).toString(16).padStart(16, '0');
}

/** The binary64 value of a 16-digit hex bit pattern. */
export function unhex(bits: string): number {
  if (!/^[0-9a-f]{16}$/u.test(bits)) throw new Error(`bad hex ${bits}`);
  VIEW.setBigUint64(0, BigInt(`0x${bits}`));
  return VIEW.getFloat64(0);
}

function hexList(text: string): number[] {
  return text.split(' ').map(unhex);
}

/** Exactly 2^k for a normal power of two, built from its bits (no `Math.pow`). */
export function pow2(k: number): number {
  if (!Number.isInteger(k) || k < -1022 || k > 1023) throw new Error(`pow2(${k}) out of range`);
  VIEW.setBigUint64(0, BigInt(k + 1023) << 52n);
  return VIEW.getFloat64(0);
}

/** `⌊log2 x⌋` of a positive normal binary64, read from its exponent field. */
export function floorLog2(value: number): number {
  if (!(value > 0) || !Number.isFinite(value)) throw new Error(`floorLog2(${value})`);
  VIEW.setFloat64(0, value);
  const exponent = Number((VIEW.getBigUint64(0) >> 52n) & 0x7ffn);
  if (exponent === 0) throw new Error(`floorLog2 of subnormal ${value}`);
  return exponent - 1023;
}

/** Multiplies by 2^k exactly, also for |k| beyond one normal power. */
function scaleBy(value: number, k: number): number {
  let result = value;
  let rest = k;
  while (rest > 1000) {
    result *= pow2(1000);
    rest -= 1000;
  }
  while (rest < -1000) {
    result *= pow2(-1000);
    rest += 1000;
  }
  return result * pow2(rest);
}

// ---------------------------------------------------------------------------------------------
// Exact dyadic arithmetic: a binary64 is n·2^e exactly.

export type Dyadic = Readonly<{ n: bigint; e: number }>;

export function dyadic(value: number): Dyadic {
  if (!Number.isFinite(value)) throw new Error('non-finite');
  VIEW.setFloat64(0, value);
  const bits = VIEW.getBigUint64(0);
  const negative = bits >> 63n === 1n;
  const exponent = Number((bits >> 52n) & 0x7ffn);
  const fraction = bits & ((1n << 52n) - 1n);
  const n = exponent === 0 ? fraction : fraction | (1n << 52n);
  const e = exponent === 0 ? -1074 : exponent - 1075;
  return { n: negative ? -n : n, e };
}

export function dMul(a: Dyadic, b: Dyadic): Dyadic {
  return { n: a.n * b.n, e: a.e + b.e };
}

export function dAdd(a: Dyadic, b: Dyadic): Dyadic {
  if (a.e <= b.e) return { n: a.n + (b.n << BigInt(b.e - a.e)), e: a.e };
  return { n: (a.n << BigInt(a.e - b.e)) + b.n, e: b.e };
}

export function dNeg(a: Dyadic): Dyadic {
  return { n: -a.n, e: a.e };
}

/** Sign of a − b. */
export function dCmp(a: Dyadic, b: Dyadic): number {
  const difference = dAdd(a, dNeg(b)).n;
  return difference > 0n ? 1 : difference < 0n ? -1 : 0;
}

function dPow2(k: number): Dyadic {
  return { n: 1n, e: k };
}

function bitLength(value: bigint): number {
  return value === 0n ? 0 : (value < 0n ? -value : value).toString(2).length;
}

/** log2 of a positive dyadic, rounded down to an integer. */
function dFloorLog2(a: Dyadic): number {
  if (a.n <= 0n) throw new Error('dFloorLog2 of non-positive');
  return bitLength(a.n) - 1 + a.e;
}

export type Rounding = 'RN' | 'RD' | 'RU';

/** Rounds the rational num/den (den > 0) to binary64 in the normal range. */
export function roundRational(num: bigint, den: bigint, mode: Rounding): number {
  if (den <= 0n) throw new Error('roundRational: den must be positive');
  if (num === 0n) return 0;
  if (num < 0n)
    return -roundRational(-num, den, mode === 'RD' ? 'RU' : mode === 'RU' ? 'RD' : mode);
  let exponent = bitLength(num) - bitLength(den) - 53;
  for (;;) {
    const scaledNum = exponent < 0 ? num << BigInt(-exponent) : num;
    const scaledDen = exponent > 0 ? den << BigInt(exponent) : den;
    let mantissa = scaledNum / scaledDen;
    const remainder = scaledNum - mantissa * scaledDen;
    if (mantissa >= 1n << 53n) {
      exponent += 1;
      continue;
    }
    if (mantissa < 1n << 52n) {
      exponent -= 1;
      continue;
    }
    if (mode === 'RN') {
      const twice = 2n * remainder - scaledDen;
      if (twice > 0n || (twice === 0n && (mantissa & 1n) === 1n)) mantissa += 1n;
    } else if (mode === 'RU' && remainder > 0n) {
      mantissa += 1n;
    }
    if (mantissa === 1n << 53n) {
      mantissa = 1n << 52n;
      exponent += 1;
    }
    if (exponent + 52 < -1022 || exponent + 52 > 1023) throw new Error('roundRational: range');
    return scaleBy(Number(mantissa), exponent);
  }
}

/** A dyadic as a rational num/den with den a positive power of two. */
function dRational(a: Dyadic): readonly [bigint, bigint] {
  return a.e >= 0 ? [a.n << BigInt(a.e), 1n] : [a.n, 1n << BigInt(-a.e)];
}

function isqrt(value: bigint): bigint {
  if (value < 0n) throw new Error('isqrt of negative');
  if (value < 2n) return value;
  let x = 1n << BigInt(Math.ceil(bitLength(value) / 2));
  for (;;) {
    const y = (x + value / x) >> 1n;
    if (y >= x) return x;
    x = y;
  }
}

/** sqrt(num/den) rounded down (RD) or up (RU) to binary64, num, den > 0. */
export function sqrtRational(num: bigint, den: bigint, mode: 'RD' | 'RU'): number {
  // Choose E with sqrt(num/den)·2^-E in [2^52, 2^53).
  let exponent = Math.floor((bitLength(num) - bitLength(den)) / 2) - 53;
  for (;;) {
    const shift = -2 * exponent;
    const scaledNum = shift >= 0 ? num << BigInt(shift) : num;
    const scaledDen = shift < 0 ? den << BigInt(-shift) : den;
    const floorQuotient = scaledNum / scaledDen;
    const root = isqrt(floorQuotient);
    if (root >= 1n << 53n) {
      exponent += 1;
      continue;
    }
    if (root < 1n << 52n) {
      exponent -= 1;
      continue;
    }
    const exact = root * root * scaledDen === scaledNum;
    let mantissa = root;
    if (mode === 'RU' && !exact) mantissa += 1n;
    return scaleBy(Number(mantissa), exponent);
  }
}

// ---------------------------------------------------------------------------------------------
// PRNG: nextXorshift32, copied by value from packages/geometry-reference/src/corpus.ts (13.5).

export function nextXorshift32(state: number): number {
  let value = state >>> 0;
  value = (value ^ (value << 13)) >>> 0;
  value = (value ^ (value >>> 17)) >>> 0;
  value = (value ^ (value << 5)) >>> 0;
  return value;
}

/** One record of a scalar drawn for a generic coordinate (used by the 53-bit draw check). */
export type GenericDraw = Readonly<{ hi: number; lo: number; scale: number; value: number }>;

export class DrawStream {
  private state: number;
  draws = 0;
  readonly generic: GenericDraw[] = [];
  constructor(seed: number) {
    this.state = seed >>> 0;
  }
  /** One draw: advances the state once and returns u = state / 2^32 in [0, 1). */
  u(): number {
    this.state = nextXorshift32(this.state);
    this.draws += 1;
    return this.state * pow2(-32);
  }
  private word(): number {
    this.state = nextXorshift32(this.state);
    this.draws += 1;
    return this.state;
  }
  int(n: number): number {
    return Math.floor(this.u() * n);
  }
  /** E3-N13: u53 = (hi·2^21 + (lo >>> 11)) / 2^53 from two draws, hi then lo. */
  u53(): readonly [number, number, number] {
    const hi = this.word();
    const lo = this.word();
    return [(hi * pow2(21) + (lo >>> 11)) * pow2(-53), hi, lo];
  }
  /** `(2·u53 − 1)·scale`, recorded for the 53-bit draw check. */
  generic53(scale: number): number {
    const [u, hi, lo] = this.u53();
    const value = (2 * u - 1) * scale;
    this.generic.push({ hi, lo, scale, value });
    return value;
  }
}

