// ---------------------------------------------------------------------------------------------
// Paths: contours of line and cubic segments.

export type Point = readonly [number, number];
type Segment =
  Readonly<{ kind: 'L'; p: Point }> | Readonly<{ kind: 'C'; c1: Point; c2: Point; p: Point }>;
export type Contour = Readonly<{ start: Point; segments: readonly Segment[]; closed: boolean }>;

function polygon(points: readonly Point[], closed = true): Contour {
  return {
    start: points[0]!,
    segments: points.slice(1).map((p) => ({ kind: 'L', p }) as const),
    closed,
  };
}

/** A rectangle `(x0,y0)–(x1,y1)` is `(x0,y0) (x1,y0) (x1,y1) (x0,y1)` (13.4). */
function rect(x0: number, y0: number, x1: number, y1: number): Contour {
  return polygon([
    [x0, y0],
    [x1, y0],
    [x1, y1],
    [x0, y1],
  ]);
}

/** Reversed point order (13.4, "Reversed"). */
function reverse(contour: Contour): Contour {
  const anchors: Point[] = [contour.start, ...contour.segments.map((s) => s.p)];
  const segments: Segment[] = [];
  for (let index = contour.segments.length - 1; index >= 0; index -= 1) {
    const segment = contour.segments[index]!;
    const target = anchors[index]!;
    segments.push(
      segment.kind === 'L'
        ? { kind: 'L', p: target }
        : { kind: 'C', c1: segment.c2, c2: segment.c1, p: target },
    );
  }
  return { start: anchors[anchors.length - 1]!, segments, closed: contour.closed };
}

function mapContour(contour: Contour, f: (p: Point) => Point): Contour {
  return {
    start: f(contour.start),
    segments: contour.segments.map((s) =>
      s.kind === 'L'
        ? { kind: 'L', p: f(s.p) }
        : { kind: 'C', c1: f(s.c1), c2: f(s.c2), p: f(s.p) },
    ),
    closed: contour.closed,
  };
}

function mapPath(path: readonly Contour[], f: (p: Point) => Point): Contour[] {
  return path.map((contour) => mapContour(contour, f));
}

function pathPoints(path: readonly Contour[]): Point[] {
  const points: Point[] = [];
  for (const contour of path) {
    points.push(contour.start);
    for (const s of contour.segments) {
      if (s.kind === 'C') points.push(s.c1, s.c2);
      points.push(s.p);
    }
  }
  return points;
}

/** Path from SVG-like commands: M, L, C (three points) and Z. */
function commands(
  ...items: readonly (
    | readonly ['M' | 'L', number, number]
    | readonly ['C', number, number, number, number, number, number]
    | readonly ['Z']
  )[]
): Contour[] {
  const contours: Contour[] = [];
  let start: Point | null = null;
  let segments: Segment[] = [];
  const flush = (closed: boolean) => {
    if (start !== null) contours.push({ start, segments, closed });
    start = null;
    segments = [];
  };
  for (const item of items) {
    if (item[0] === 'M') {
      flush(false);
      start = [item[1], item[2]];
    } else if (item[0] === 'L') segments.push({ kind: 'L', p: [item[1], item[2]] });
    else if (item[0] === 'C')
      segments.push({
        kind: 'C',
        c1: [item[1], item[2]],
        c2: [item[3], item[4]],
        p: [item[5], item[6]],
      });
    else flush(true);
  }
  flush(false);
  return contours;
}

/** A path from a flat point list and an M/C/Z verb string. */
function fromVerbs(verbs: string, values: readonly number[]): Contour[] {
  const items: (
    | readonly ['M' | 'L', number, number]
    | readonly ['C', number, number, number, number, number, number]
    | readonly ['Z']
  )[] = [];
  let index = 0;
  const take = () => values[index++]!;
  for (const verb of verbs) {
    if (verb === 'M' || verb === 'L') items.push([verb, take(), take()]);
    else if (verb === 'C') items.push(['C', take(), take(), take(), take(), take(), take()]);
    else items.push(['Z']);
  }
  if (index !== values.length) throw new Error('fromVerbs: point count');
  return commands(...items);
}

/** Canonical `path` object: verbs string and hex points (13.2). */
function encodePath(path: readonly Contour[]): { points: string[]; verbs: string } {
  let verbs = '';
  const points: string[] = [];
  for (const contour of path) {
    verbs += 'M';
    points.push(hex(contour.start[0]), hex(contour.start[1]));
    for (const s of contour.segments) {
      verbs += s.kind;
      if (s.kind === 'C') points.push(hex(s.c1[0]), hex(s.c1[1]), hex(s.c2[0]), hex(s.c2[1]));
      points.push(hex(s.p[0]), hex(s.p[1]));
    }
    if (contour.closed) verbs += 'Z';
  }
  return { points, verbs };
}

// ---------------------------------------------------------------------------------------------
// Page helpers of apps/playground/src/p3-b2-strokes-scene.ts, copied by value (13.4).

export const KAPPA = unhex('3fe1ac5111534a23'); // 0.5522847498307936

/** `circle(cx, cy, r)`: four cubics starting at (cx + r, cy); binary64 basic operations only. */
function circle(cx: number, cy: number, r: number): Contour {
  const anchors: Point[] = [
    [cx + r, cy],
    [cx, cy + r],
    [cx - r, cy],
    [cx, cy - r],
    [cx + r, cy],
  ];
  const segments: Segment[] = [];
  for (let index = 0; index < 4; index += 1) {
    const [x0, y0] = anchors[index]!;
    const [x1, y1] = anchors[index + 1]!;
    const t0 = [-(y0 - cy), x0 - cx] as const;
    const t1 = [-(y1 - cy), x1 - cx] as const;
    segments.push({
      kind: 'C',
      c1: [x0 + KAPPA * t0[0], y0 + KAPPA * t0[1]],
      c2: [x1 - KAPPA * t1[0], y1 - KAPPA * t1[1]],
      p: [x1, y1],
    });
  }
  return { start: anchors[0]!, segments, closed: true };
}

/**
 * Chevron arms `[dx, dy] = [len·sin(h°), len·cos(h°)]` as hex, keyed `h/len`. Each is the value
 * of the page helper's binary64 expression `length * Math.sin((h * Math.PI) / 180)` (and
 * `Math.cos`) with the sine and cosine correctly rounded (E3-N10).
 */
export const CHEVRON_HEX: Readonly<Record<string, readonly [string, string]>> = {
  '6/60': ['4019163a918891f4', '404dd5ed9ba8e14a'],
  '3/60': ['40091f0ad460cc7c', '404df5798e41b7bb'],
  '1/60': ['3ff0c11a78d13f4c', '404dfed48e765491'],
  '14/60': ['402d07d733b66d8b', '404d1bdf05821e83'],
  '14.4775/60': ['402dfffe6167faab', '404d0c20e0fd6620'],
  '15/60': ['402f0eebcaf3ac4e', '404cfa4f72d43324'],
  '45/52': ['40426280b3476096', '40426280b3476097'],
  '30/52': ['4039ffffffffffff', '40468443dcc7be4b'],
  '15/52': ['402aeacc5a8eeaaa', '40491d33c9eb1b41'],
};

/** `chevron(h, len, apexY)` of the page: apex (0, apexY), arms opening downward by h each. */
function chevron(halfAngle: number, length: number, apexY: number): Contour {
  const entry = CHEVRON_HEX[`${halfAngle}/${length}`];
  if (entry === undefined) throw new Error(`no chevron table entry ${halfAngle}/${length}`);
  const dx = unhex(entry[0]);
  const dy = unhex(entry[1]);
  return polygon(
    [
      [-dx, apexY + dy],
      [0, apexY],
      [dx, apexY + dy],
    ],
    false,
  );
}

