/**
 * `depth-positive/star` and `depth-positive/zero-closure` contours of
 * tests/geometry/native-depth-positive-cubic/fixtures.ts, every source verb a cubic.
 */
export const DEPTH_POSITIVE_HEX: Readonly<Record<string, string>> = {
  'depth-positive/star':
    'MCCCZMCCCCZ|c008000000000000 0000000000000000 bff0000000000000 3fc0000000000000 3ff0000000000000 3fc0000000000000 4008000000000000 0000000000000000 4008000000000000 0000000000000000 0000000000000000 c024000000000000 0000000000000000 c024000000000000 0000000000000000 c024000000000000 c008000000000000 0000000000000000 c008000000000000 0000000000000000 3ff0000000000000 bff0000000000000 3ff0000000000000 bff0000000000000 4000000000000000 bff0000000000000 4000000000000000 bff0000000000000 4000000000000000 bff0000000000000 4000000000000000 3ff0000000000000 4000000000000000 3ff0000000000000 4000000000000000 3ff0000000000000 3ff0000000000000 3ff0000000000000 3ff0000000000000 3ff0000000000000 3ff0000000000000 3ff0000000000000 3ff0000000000000 bff0000000000000 3ff0000000000000 bff0000000000000',
  'depth-positive/zero-closure':
    'MCCCMCCC|c008000000000000 0000000000000000 c008000000000000 0000000000000000 c008000000000000 0000000000000000 c008000000000000 0000000000000000 bff0000000000000 3fc0000000000000 3ff0000000000000 3fc0000000000000 4008000000000000 0000000000000000 4008000000000000 0000000000000000 0000000000000000 c024000000000000 0000000000000000 c024000000000000 3ff0000000000000 bff0000000000000 3ff0000000000000 bff0000000000000 4000000000000000 bff0000000000000 4000000000000000 bff0000000000000 4000000000000000 bff0000000000000 4000000000000000 3ff0000000000000 4000000000000000 3ff0000000000000 4000000000000000 3ff0000000000000 3ff0000000000000 3ff0000000000000 3ff0000000000000 3ff0000000000000',
};

function ob5Path(key: string): Contour[] {
  const text = OB5_HEX[key];
  if (text === undefined) throw new Error(`no OB5 path ${key}`);
  return fromVerbs(`M${'C'.repeat(32)}Z`, hexList(text));
}

function depthPositivePath(key: string): Contour[] {
  const text = DEPTH_POSITIVE_HEX[key];
  if (text === undefined) throw new Error(`no depth-positive path ${key}`);
  const [verbs, values] = text.split('|') as [string, string];
  return fromVerbs(verbs, hexList(values));
}

function pairsOf(values: readonly number[]): Point[] {
  const points: Point[] = [];
  for (let index = 0; index < values.length; index += 2)
    points.push([values[index]!, values[index + 1]!]);
  return points;
}

// ---------------------------------------------------------------------------------------------
// Paint and rows

export type Cap = 'butt' | 'round' | 'square';
export type Join = 'miter' | 'round' | 'bevel';
export type Paint =
  | Readonly<{ kind: 'fill'; rule: 'nonzero' | 'evenodd' }>
  | Readonly<{ kind: 'stroke'; width: number; cap: Cap; join: Join; miterLimit: number }>;

const NZ: Paint = { kind: 'fill', rule: 'nonzero' };
const EO: Paint = { kind: 'fill', rule: 'evenodd' };

function stroke(width: number, cap: Cap = 'butt', join: Join = 'miter', miterLimit = 4): Paint {
  return { kind: 'stroke', width, cap, join, miterLimit };
}

export type Stratum =
  'C1' | 'C2' | 'C3' | 'C4' | 'C5' | 'C6' | 'C7' | 'C8' | 'C9' | 'C10' | 'C11' | 'C12';

/** C4 per-case context: the local gap for the case. */
type GapContext = Readonly<{ gLocal: number }>;

export type NamedRow = Readonly<{
  stratum: Stratum;
  row: string;
  source: string;
  paint: Paint;
  path: (context: GapContext) => Contour[];
  joint: Readonly<{ group: string; role: 'fill' | 'stroke' }> | null;
  opacity: number;
  /** C4 only: target gap g, tangent t and κ² (null for g = 0). */
  gap: Readonly<{ g: number; tangent: Point; kappa2: number }> | null;
}>;

function named(
  stratum: Stratum,
  row: string,
  source: string,
  paint: Paint,
  path: Contour[] | ((context: GapContext) => Contour[]),
  extra: Partial<Pick<NamedRow, 'joint' | 'opacity' | 'gap'>> = {},
): NamedRow {
  return {
    stratum,
    row,
    source,
    paint,
    path: typeof path === 'function' ? path : () => path,
    joint: extra.joint ?? null,
    opacity: extra.opacity ?? 1,
    gap: extra.gap ?? null,
  };
}

const ANNEX = 'e3-annex';

// ---------------------------------------------------------------------------------------------
// E3-C1: fill, lines, snapped (40 rows).

const GRID_Q: Point = [37 / 256, 91 / 256];

function square(cx: number, cy: number, side: number): Contour {
  const h = side / 2;
  return rect(cx - h, cy - h, cx + h, cy + h);
}

/** C1 base shapes, before the grid suffix: [row, paint, contours, grids]. */
function c1Shapes(): readonly (readonly [string, Paint, Contour[], readonly ('I' | 'Q')[]])[] {
  const both = ['I', 'Q'] as const;
  const only = ['I'] as const;
  const pentagram = polygon([
    [0, -10],
    [6, 8],
    [-10, -3],
    [10, -3],
    [-6, 8],
  ]);
  const nested = [square(0, 0, 24), reverse(square(0, 0, 16)), square(0, 0, 8)];
  const shapes: [string, Paint, Contour[], readonly ('I' | 'Q')[]][] = [
    ['s01', NZ, [rect(0, 0, 16, 8)], both],
    [
      's02',
      NZ,
      [
        polygon([
          [0, 0],
          [16, 0],
          [4, 12],
        ]),
      ],
      both,
    ],
    [
      's03',
      NZ,
      [
        polygon([
          [0, 0],
          [16, 0],
          [16, 4],
          [4, 4],
          [4, 12],
          [0, 12],
        ]),
      ],
      both,
    ],
    ['s04', NZ, [pentagram], both],
    ['s05', EO, [pentagram], both],
    ['s06', NZ, nested, both],
    ['s07', EO, nested, both],
    ['s08', NZ, [square(0, 0, 16), reverse(square(0, 0, 8))], both],
    ['s09', NZ, [rect(0, 0, 16, 8), rect(8, 0, 24, 6)], both],
    ['s10', NZ, [rect(0, 0, 16, 8), rect(16, 0, 32, 8)], both],
    [
      's11',
      NZ,
      [
        rect(0, 0, 16, 8),
        polygon([
          [20, 0],
          [28, 0],
          [20, 0],
        ]),
      ],
      both,
    ],
    [
      's12',
      NZ,
      [
        polygon([
          [0, 0],
          [8, 8],
          [16, 0],
          [16, 16],
          [8, 8],
          [0, 16],
        ]),
      ],
      both,
    ],
    [
      's13',
      NZ,
      [
        polygon(
          pairsOf([
            0, 0, 32, 0, 32, 16, 28, 16, 28, 4, 24, 4, 24, 16, 20, 16, 20, 4, 16, 4, 16, 16, 12, 16,
            12, 4, 8, 4, 8, 16, 4, 16, 4, 4, 0, 4,
          ]),
        ),
      ],
      both,
    ],
    [
      's14',
      NZ,
      [
        polygon([
          [0, 0],
          [8, 0],
          [16, 0],
          [16, 8],
          [0, 8],
        ]),
      ],
      both,
    ],
    ['s15', NZ, [rect(0, 0, 16, 16), rect(8, 8, 24, 24)], only],
    ['s16', EO, [rect(0, 0, 16, 16), rect(8, 8, 24, 24)], only],
  ];
  const needles = [1e3, 1e4, 1e5, 1e6];
  needles.forEach((a, index) =>
    shapes.push([
      `s${String(17 + index)}`,
      NZ,
      [
        polygon([
          [0, 0],
          [a, 0],
          [0, 1],
        ]),
      ],
      only,
    ]),
  );
  const ks = [24, 32, 40];
  ks.forEach((k, index) =>
    shapes.push([
      `s${String(21 + index)}`,
      NZ,
      [
        polygon([
          [-64, 0],
          [pow2(k), 0],
          [-64, 64],
        ]),
      ],
      only,
    ]),
  );
  ks.forEach((k, index) =>
    shapes.push([`s${String(24 + index)}`, NZ, [rect(-64, 0, pow2(k), pow2(k - 2))], only]),
  );
  return shapes;
}

function c1Source(row: string): string {
  const index = Number(row.slice(1));
  if (index >= 21 && index <= 23) return `T03:S/TRI/k${String(24 + 8 * (index - 21))}`;
  if (index >= 24) return `T03:S/RECT/k${String(24 + 8 * (index - 24))}`;
  return `${ANNEX}/${row}`;
}

function c1Rows(): NamedRow[] {
  const rows: NamedRow[] = [];
  for (const [row, paint, contours, grids] of c1Shapes())
    for (const grid of grids) {
      const path =
        grid === 'I' ? contours : mapPath(contours, ([x, y]) => [x + GRID_Q[0], y + GRID_Q[1]]);
      rows.push(named('C1', `${row}-${grid}`, c1Source(row), paint, path));
    }
  if (rows.length !== 40) throw new Error(`C1 has ${rows.length} rows`);
  return rows;
}

// ---------------------------------------------------------------------------------------------
// E3-C3: fill, cubics (30 rows).

function scalePath(path: readonly Contour[], sx: number, sy: number): Contour[] {
  return mapPath(path, ([x, y]) => [x * sx, y * sy]);
}

function c3Rows(): NamedRow[] {
  const unitEllipse = (sx: number, sy: number) => scalePath([circle(0, 0, 1)], sx, sy);
  const cusp = (x: number) => commands(['M', 0, 0], ['C', 8, 8, x, 8, 8, 0], ['Z']);
  const crossing = [...unitEllipse(12, 4), ...unitEllipse(4, 12)];
  const concentric = [circle(0, 0, 12), reverse(circle(0, 0, 8)), circle(0, 0, 4)];
  const rows: NamedRow[] = [
    named('C3', 'c01', `${ANNEX}/c01`, NZ, [circle(0, 0, 8)]),
    named('C3', 'c02', `${ANNEX}/c02`, NZ, unitEllipse(12, 4)),
    named(
      'C3',
      'c03',
      `${ANNEX}/c03`,
      NZ,
      commands(
        ['M', 0, 0],
        ['C', 4, 8, 8, -8, 12, 0],
        ['L', 12, -6],
        ['C', 8, -14, 4, 2, 0, -6],
        ['Z'],
      ),
    ),
    named(
      'C3',
      'c04',
      `${ANNEX}/c04`,
      NZ,
      commands(['M', 0, 0], ['C', 12, 12, -4, 12, 8, 0], ['Z']),
    ),
    named(
      'C3',
      'c05',
      `${ANNEX}/c05`,
      EO,
      commands(['M', 0, 0], ['C', 12, 12, -4, 12, 8, 0], ['Z']),
    ),
    named('C3', 'c06', `${ANNEX}/c06`, NZ, cusp(0)),
    named('C3', 'c07', `${ANNEX}/c07`, NZ, cusp(pow2(-10))),
    named('C3', 'c08', `${ANNEX}/c08`, NZ, cusp(pow2(-20))),
    named('C3', 'c09', `${ANNEX}/c09`, NZ, cusp(pow2(-40))),
    named(
      'C3',
      'c10',
      `${ANNEX}/c10`,
      NZ,
      commands(['M', 0, 0], ['C', 4, 8, 8, -8, 12, 0], ['L', 12, -4], ['L', 0, -4], ['Z']),
    ),
    named('C3', 'c11', `${ANNEX}/c11`, NZ, crossing),
    named('C3', 'c12', `${ANNEX}/c12`, EO, crossing),
    named('C3', 'c13', `${ANNEX}/c13`, NZ, [
      circle(0, 0, 12),
      reverse(circle(-5, 0, 3)),
      reverse(circle(5, 0, 3)),
    ]),
  ];
  const rings = ['OB5-W2', 'OB5-W4', 'OB5-W8', 'OB5-W2U', 'OB5-W4U', 'OB5-W8U'];
  rings.forEach((ring, index) =>
    rows.push(
      named('C3', `c${String(14 + index)}`, `AL-OB5/${ring}/path0`, NZ, ob5Path(`${ring}/path0`)),
    ),
  );
  let index = 20;
  for (const id of ['depth-positive/star', 'depth-positive/zero-closure'])
    for (const paint of [NZ, EO]) {
      rows.push(named('C3', `c${String(index)}`, id, paint, depthPositivePath(id)));
      index += 1;
    }
  const k8 = 8 * KAPPA;
  rows.push(
    named(
      'C3',
      'c24',
      `${ANNEX}/c24`,
      NZ,
      commands(['M', 0, 0], ['L', 8, 0], ['C', 8, k8, k8, 8, 0, 8], ['Z']),
    ),
    named(
      'C3',
      'c25',
      `${ANNEX}/c25`,
      NZ,
      commands(['M', 0, 0], ['C', 0, 0, 8, 8, 8, 8], ['L', 0, 8], ['Z']),
    ),
    named(
      'C3',
      'c26',
      `${ANNEX}/c26`,
      NZ,
      commands(['M', 0, 0], ['L', 0, 16], ['C', 12, 16, 12, 0, 0, 0], ['Z']),
    ),
    named('C3', 'c27', `${ANNEX}/c27`, NZ, [circle(0, 0, 4096)]),
    named('C3', 'c28', `${ANNEX}/c28`, NZ, concentric),
    named('C3', 'c29', `${ANNEX}/c29`, EO, concentric),
    named(
      'C3',
      'c30',
      `${ANNEX}/c30`,
      NZ,
      commands(
        ['M', 0, 0],
        ['C', 8, 8, 0, 8, 8, 0],
        ['C', 16, 8, 8, 8, 16, 0],
        ['L', 16, -4],
        ['L', 0, -4],
        ['Z'],
      ),
    ),
  );
  if (rows.length !== 30) throw new Error(`C3 has ${rows.length} rows`);
  return rows;
}

// ---------------------------------------------------------------------------------------------
// E3-C4: near-coincidence, fill (24 rows). `g` in the shapes is the per-case local gap.

const C4_GAPS = [pow2(-3), pow2(-8), pow2(-16)] as const;

function c4Rows(): NamedRow[] {
  const rows: NamedRow[] = [];
  let index = 1;
  const add = (
    shape: (g: number) => Contour[],
    tangent: Point | null,
    kappa2: number,
    withZero: boolean,
  ) => {
    for (const g of [...C4_GAPS, ...(withZero ? [0] : [])]) {
      const row = `n${String(index).padStart(2, '0')}`;
      index += 1;
      rows.push(
        named('C4', row, `${ANNEX}/${row}`, NZ, ({ gLocal }) => shape(g === 0 ? 0 : gLocal), {
          gap: g === 0 || tangent === null ? null : { g, tangent, kappa2 },
        }),
      );
    }
  };
  add((g) => [rect(0, 0, 16, 8), rect(0, 8 + g, 16, 16 + g)], [1, 0], 1, true);
  add(
    (g) => [
      polygon([
        [0, 0],
        [16, 0],
        [0, 16],
      ]),
      polygon([
        [16 + g, g],
        [16 + g, 16 + g],
        [g, 16 + g],
      ]),
    ],
    [1, -1],
    2,
    true,
  );
  add((g) => [circle(0, 8 + g, 8), rect(-16, -8, 16, 0)], [1, 0], 1, false);
  add((g) => [circle(0, 0, 8), circle(16 + g, 0, 8)], [0, 1], 1, false);
  add((g) => [rect(0, 0, 16, 8), rect(0, 8 - g, 16, 16)], [1, 0], 1, false);
  add((g) => [rect(0, 0, 16, 16), reverse(rect(g, 4, 12, 12))], [0, 1], 1, false);
  add((g) => [rect(0, 0, 16, 16), reverse(rect(4, 4, 4 + g, 12))], [0, 1], 1, false);
  rows.push(
    named('C4', 'n24', `${ANNEX}/n24`, NZ, [
      polygon([
        [0, 0],
        [16, 0],
        [8, 8],
      ]),
      polygon([
        [16, 16],
        [0, 16],
        [8, 8],
      ]),
    ]),
  );
  if (rows.length !== 24) throw new Error(`C4 has ${rows.length} rows`);
  return rows;
}

/** Exact S = d·z·L entries as dyadics. */
function exactS(l: Matrix, zoom: number, dpr: number): readonly [Dyadic, Dyadic, Dyadic, Dyadic] {
  const dz = dMul(dyadic(dpr), dyadic(zoom));
  return [
    dMul(dz, dyadic(l[0])),
    dMul(dz, dyadic(l[1])),
    dMul(dz, dyadic(l[2])),
    dMul(dz, dyadic(l[3])),
  ];
}

export type GapRecord = Readonly<{ gLocal: number; m: number; lo: number; hi: number; g: number }>;

/**
 * E3-N7: `m = ⌊log2(κ·|det S|·|t|/|S·t|)⌋` by exact comparison of squares, and the gap. `phys`
 * encloses the slab (normal-direction) gap. For the two-circle rows n12–n14 it is a lower bound:
 * their true minimum physical gap lies in [slab, |S·(g_local, 0)|] (review round 1, F1).
 */
export function c4Gap(
  gap: Readonly<{ g: number; tangent: Point; kappa2: number }>,
  l: Matrix,
  zoom: number,
  dpr: number,
): GapRecord {
  const [s00, s01, s10, s11] = exactS(l, zoom, dpr);
  const det = dAdd(dMul(s00, s11), dNeg(dMul(s01, s10)));
  const tx = dyadic(gap.tangent[0]);
  const ty = dyadic(gap.tangent[1]);
  const t2 = dAdd(dMul(tx, tx), dMul(ty, ty));
  const stx = dAdd(dMul(s00, tx), dMul(s01, ty));
  const sty = dAdd(dMul(s10, tx), dMul(s11, ty));
  const st2 = dAdd(dMul(stx, stx), dMul(sty, sty));
  const a = dMul(dMul(dyadic(gap.kappa2), dMul(det, det)), t2); // κ²·(det S)²·|t|²
  // Largest m with 4^m·|S·t|² ≤ a.
  let m = Math.floor((dFloorLog2(a) - dFloorLog2(st2)) / 2) + 1;
  while (dCmp(dMul(dPow2(2 * m), st2), a) > 0) m -= 1;
  while (dCmp(dMul(dPow2(2 * (m + 1)), st2), a) <= 0) m += 1;
  const gLocal = gap.g * pow2(-m);
  // Physical gap squared: g_local²·a/|S·t|².
  const gl = dyadic(gLocal);
  const [num, den] = (() => {
    const top = dMul(dMul(gl, gl), a);
    const [tn, td] = dRational(top);
    const [bn, bd] = dRational(st2);
    return [tn * bd, td * bn] as const;
  })();
  const lo = sqrtRational(num, den, 'RD');
  const hi = sqrtRational(num, den, 'RU');
  // The exact gap lies in [g, 2g); its enclosure [lo, hi] therefore has lo ≥ g and lo < 2g.
  if (!(lo >= gap.g && lo < 2 * gap.g && hi <= 2 * gap.g))
    throw new Error(`C4 gap outside [g, 2g): ${lo} ${hi} ${gap.g}`);
  return { gLocal, m, lo, hi, g: gap.g };
}

