// ---------------------------------------------------------------------------------------------
// Camera (13.7), extents (13.5) and the canonical case object (13.2).

export type Placement = 'center' | 'partial' | 'far' | 'pan';

/** World bounding box of L·x + t over the path's points, binary64 operations. */
function worldBox(
  points: readonly Point[],
  l: Matrix,
  t: Point,
): readonly [number, number, number, number] {
  if (points.length === 0) return [t[0], t[1], t[0], t[1]];
  let minX = Infinity;
  let minY = Infinity;
  let maxX = -Infinity;
  let maxY = -Infinity;
  for (const [x, y] of points) {
    const wx = l[0] * x + l[1] * y + t[0];
    const wy = l[2] * x + l[3] * y + t[1];
    minX = Math.min(minX, wx);
    minY = Math.min(minY, wy);
    maxX = Math.max(maxX, wx);
    maxY = Math.max(maxY, wy);
  }
  return [minX, minY, maxX, maxY];
}

function snap256(value: number): number {
  return Math.floor(value * 256 + 0.5) / 256;
}

/** Center (or min-corner, for partial) camera, snapped to the 2^-8 grid. */
function camera(
  points: readonly Point[],
  l: Matrix,
  t: Point,
  zoom: number,
  anchor: 'mid' | 'min',
): Point {
  const [minX, minY, maxX, maxY] = worldBox(points, l, t);
  const ax = anchor === 'mid' ? (minX + maxX) / 2 : minX;
  const ay = anchor === 'mid' ? (minY + maxY) / 2 : minY;
  return [snap256(ax - 320 / zoom), snap256(ay - 180 / zoom)];
}

/** `E_cur`: the larger side of the binary64 box of d·z·(L·x) over the points (13.5). */
export function physicalExtent(
  points: readonly Point[],
  l: Matrix,
  zoom: number,
  dpr: number,
): number {
  const scale = dpr * zoom;
  let minX = Infinity;
  let minY = Infinity;
  let maxX = -Infinity;
  let maxY = -Infinity;
  for (const [x, y] of points) {
    const px = scale * (l[0] * x + l[1] * y);
    const py = scale * (l[2] * x + l[3] * y);
    minX = Math.min(minX, px);
    minY = Math.min(minY, py);
    maxX = Math.max(maxX, px);
    maxY = Math.max(maxY, py);
  }
  return Math.max(maxX - minX, maxY - minY);
}

const PAN: Point = [unhex('3f80000000000000'), unhex('3fd7c36113404ea5')];
const FAR: Point = [unhex('4170000000000000'), -unhex('4170000000000000')];

function encodePaint(paint: Paint): Record<string, string> {
  return paint.kind === 'fill'
    ? { kind: 'fill', rule: paint.rule }
    : {
        cap: paint.cap,
        join: paint.join,
        kind: 'stroke',
        miterLimit: hex(paint.miterLimit),
        width: hex(paint.width),
      };
}

export type CanonicalCase = Readonly<Record<string, unknown>>;

type CaseInput = Readonly<{
  stratum: Stratum;
  row: string;
  source: string;
  transform: TransformId | 'edge';
  l: Matrix;
  t: Point;
  zoom: number;
  dpr: number;
  placement: Placement;
  servedOffset: number;
  path: Contour[];
  paint: Paint;
  joint: NamedRow['joint'];
  opacity: number;
  sizeClass: string | null;
  gap: GapRecord | null;
  duplicateOf: string | null;
}>;

export function caseId(
  stratum: string,
  row: string,
  transform: string,
  zoom: number,
  dpr: number,
  placement: string,
  k: number,
): string {
  return `${stratum}/${row}/${transform}/z${zoomLabel(zoom)}-d${String(dpr)}/${placement}/k${String(k)}`;
}

function buildCase(input: CaseInput, index: number): CanonicalCase {
  let path = input.path;
  let t = input.t;
  let partial: Record<string, unknown> | null = null;
  let c: Point;
  if (input.placement === 'partial') {
    const extent = physicalExtent(pathPoints(path), input.l, input.zoom, input.dpr);
    const k = 12 - floorLog2(extent);
    path = mapPath(path, ([x, y]) => [scaleBy(x, k), scaleBy(y, k)]);
    const realized = physicalExtent(pathPoints(path), input.l, input.zoom, input.dpr);
    const omegaLong = 640 * input.dpr + 4;
    if (!(realized > omegaLong)) throw new Error(`partial extent ${realized} does not exceed Ω`);
    partial = { extent: hex(realized), scaleExponent: k };
    c = camera(pathPoints(path), input.l, t, input.zoom, 'min');
  } else {
    if (input.placement === 'far') t = [t[0] + FAR[0], t[1] + FAR[1]];
    c = camera(pathPoints(path), input.l, t, input.zoom, 'mid');
    if (input.placement === 'pan') c = [c[0] + PAN[0], c[1] + PAN[1]];
  }
  return {
    camera: { c: [hex(c[0]), hex(c[1])], dpr: hex(input.dpr), zoom: hex(input.zoom) },
    corpus: A04_CORPUS_VERSION,
    duplicateOf: input.duplicateOf,
    gap:
      input.gap === null
        ? null
        : {
            local: hex(input.gap.gLocal),
            m: input.gap.m,
            phys: [hex(input.gap.lo), hex(input.gap.hi)],
            target: hex(input.gap.g),
          },
    id: caseId(
      input.stratum,
      input.row,
      input.transform,
      input.zoom,
      input.dpr,
      input.placement,
      input.servedOffset,
    ),
    index,
    joint: input.joint,
    opacity: hex(input.opacity),
    paint: encodePaint(input.paint),
    partial,
    path: encodePath(path),
    placement: input.placement,
    row: input.row,
    servedOffset: input.servedOffset,
    sizeClass: input.sizeClass,
    source: input.source,
    stratum: input.stratum,
    transform: input.transform,
    viewport: [VIEWPORT[0], VIEWPORT[1]],
    world: { l: input.l.map(hex), t: [hex(t[0]), hex(t[1])] },
  };
}

/** Canonical serialization (5.1): keys sorted at every level, no whitespace. */
export function serializeCase(value: unknown): string {
  if (value === null || typeof value !== 'object') return JSON.stringify(value);
  if (Array.isArray(value)) return `[${value.map(serializeCase).join(',')}]`;
  const record = value as Record<string, unknown>;
  const keys = Object.keys(record).sort();
  return `{${keys.map((key) => `${JSON.stringify(key)}:${serializeCase(record[key])}`).join(',')}}`;
}

// ---------------------------------------------------------------------------------------------
// Generated rows (13.5).

export const A04_SEEDS = Object.freeze({
  C1: 1,
  C2: 0x1234_5678,
  C3: 0x9e37_79b9,
  C5C9: 0xdead_beef,
});

const SIZE_CLASSES = [
  ['sub', -4, 0],
  ['small', 0, 4],
  ['medium', 4, 9],
  ['large', 9, 13],
] as const;
const CAPS: readonly Cap[] = ['butt', 'round', 'square'];
const JOINS: readonly Join[] = ['miter', 'round', 'bevel'];
const MITER_LIMITS = [1, unhex('3ff6a09e667f3bcd'), 4, 10, 100] as const;

export type GeneratedRow = Readonly<{
  stratum: 'C1' | 'C2' | 'C3' | 'C5' | 'C9';
  row: string;
  source: string;
  path: Contour[];
  fill: 'nonzero' | 'evenodd' | null;
  widthExponent: number | null;
  cap: Cap | null;
  join: Join | null;
  miterLimit: number | null;
  transform: TransformId;
  t: Point;
  sizeClass: (typeof SIZE_CLASSES)[number][0];
  b: number;
}>;

/** Exact pseudo-angle order about the origin: angle in [0, 2π) from +x, then distance. */
function angleCompare(p: Point, q: Point): number {
  const half = ([x, y]: Point) => {
    if (x === 0 && y === 0) return -1;
    return y > 0 || (y === 0 && x > 0) ? 0 : 1;
  };
  const hp = half(p);
  const hq = half(q);
  if (hp !== hq) return hp - hq;
  if (hp >= 0) {
    const cross = dAdd(dMul(dyadic(p[0]), dyadic(q[1])), dNeg(dMul(dyadic(p[1]), dyadic(q[0]))));
    if (cross.n > 0n) return -1;
    if (cross.n < 0n) return 1;
  }
  const dp = dAdd(dMul(dyadic(p[0]), dyadic(p[0])), dMul(dyadic(p[1]), dyadic(p[1])));
  const dq = dAdd(dMul(dyadic(q[0]), dyadic(q[0])), dMul(dyadic(q[1]), dyadic(q[1])));
  return dCmp(dp, dq);
}

function sortByAngle(points: Point[]): Point[] {
  return points.slice().sort(angleCompare);
}

function drawGeneratedRow(
  stratum: GeneratedRow['stratum'],
  stream: DrawStream,
  seed: number,
  drawIndex: number,
): GeneratedRow {
  const coord = (): number => (stratum === 'C1' ? (2 * stream.u() - 1) * 64 : stream.generic53(64));
  const points = (n: number): Point[] => {
    const result: Point[] = [];
    for (let i = 0; i < n; i += 1) {
      const x = coord();
      const y = coord();
      result.push([x, y]);
    }
    return result;
  };
  let path: Contour[];
  if (stratum === 'C1' || stratum === 'C2') {
    const family = stream.int(4);
    if (family === 0 || family === 2) {
      const n = 3 + stream.int(10);
      const sorted = sortByAngle(points(n));
      path = [polygon(sorted)];
      if (family === 2)
        path.push(reverse(polygon(sorted.map(([x, y]) => [x / 4, y / 4] as const))));
    } else if (family === 1) {
      path = [polygon(points(4 + stream.int(6)))];
    } else {
      const m = 2 + stream.int(3);
      path = [];
      for (let i = 0; i < m; i += 1) {
        const [[x0, y0], [x1, y1]] = points(2) as [Point, Point];
        path.push(rect(Math.min(x0, x1), Math.min(y0, y1), Math.max(x0, x1), Math.max(y0, y1)));
      }
    }
    if (stratum === 'C1') {
      const q = 8 * stream.int(2);
      const g = pow2(q);
      path = mapPath(path, ([x, y]) => [Math.floor(x * g + 0.5) / g, Math.floor(y * g + 0.5) / g]);
    }
  } else if (stratum === 'C3') {
    const family = stream.int(3);
    if (family === 1) {
      const [p0, p1, p2, p3] = points(4) as [Point, Point, Point, Point];
      path = [{ start: p0, segments: [{ kind: 'C', c1: p1, c2: p2, p: p3 }], closed: true }];
    } else {
      const n = 2 + stream.int(7);
      const anchors = sortByAngle(points(n));
      const segments: Segment[] = [];
      for (let i = 0; i < n; i += 1) {
        const a = anchors[i]!;
        const b = anchors[(i + 1) % n]!;
        const d1 = [coord() / 4, coord() / 4] as const;
        const d2 = [coord() / 4, coord() / 4] as const;
        const c1: Point = [a[0] + (b[0] - a[0]) / 3 + d1[0], a[1] + (b[1] - a[1]) / 3 + d1[1]];
        const c2: Point = [
          a[0] + (2 * (b[0] - a[0])) / 3 + d2[0],
          a[1] + (2 * (b[1] - a[1])) / 3 + d2[1],
        ];
        segments.push({ kind: 'C', c1, c2, p: b });
      }
      const ring: Contour = { start: anchors[0]!, segments, closed: true };
      path = [ring];
      if (family === 2) path.push(reverse(mapContour(ring, ([x, y]) => [x / 4, y / 4])));
    }
  } else if (stratum === 'C5') {
    const n = 2 + stream.int(7);
    const vertices = points(n);
    const closed = stream.int(10) < 3;
    path = [polygon(vertices, closed)];
  } else {
    const m = 1 + stream.int(4);
    const [start] = points(1) as [Point];
    const segments: Segment[] = [];
    for (let i = 0; i < m; i += 1) {
      const [c1, c2, p] = points(3) as [Point, Point, Point];
      segments.push({ kind: 'C', c1, c2, p });
    }
    path = [{ start, segments, closed: false }];
  }
  let fill: GeneratedRow['fill'] = null;
  let widthExponentDraw: number | null = null;
  let cap: Cap | null = null;
  let join: Join | null = null;
  let miterLimit: number | null = null;
  if (stratum === 'C5' || stratum === 'C9') {
    widthExponentDraw = stream.int(12);
    cap = CAPS[stream.int(3)]!;
    join = JOINS[stream.int(3)]!;
    miterLimit = MITER_LIMITS[stream.int(5)]!;
  } else {
    fill = stream.int(2) === 0 ? 'nonzero' : 'evenodd';
  }
  const transform = TRANSFORM_IDS[stream.int(8)]!;
  const kind = stream.int(3);
  let t: Point = [0, 0];
  if (kind === 1) {
    const tx = Math.floor((2 * stream.u() - 1) * 1024);
    const ty = Math.floor((2 * stream.u() - 1) * 1024);
    t = [tx, ty];
  } else if (kind === 2) {
    const tx = stream.generic53(1024);
    const ty = stream.generic53(1024);
    t = [tx, ty];
  }
  const [sizeClass, lo, hi] = SIZE_CLASSES[stream.int(4)]!;
  const b = lo + stream.int(hi - lo);
  const draw = String(drawIndex).padStart(4, '0');
  return {
    stratum,
    row: `g${draw}`,
    source: `generated:0x${seed.toString(16).padStart(8, '0')}:${draw}`,
    path,
    fill,
    widthExponent: widthExponentDraw,
    cap,
    join,
    miterLimit,
    transform,
    t,
    sizeClass,
    b,
  };
}

export type GeneratedStreams = Readonly<{
  rows: Readonly<Record<'C1' | 'C2' | 'C3' | 'C5' | 'C9', readonly GeneratedRow[]>>;
  streams: readonly DrawStream[];
}>;

const GENERATED_COUNTS = { C1: 200, C2: 200, C3: 300, C5: 150, C9: 150 } as const;

/** Draws every generated row (E3-N8 seeds; C5 then C9 on one stream). */
export function drawGeneratedRows(): GeneratedStreams {
  const draw = (
    stratum: GeneratedRow['stratum'],
    stream: DrawStream,
    seed: number,
    count: number,
    first: number,
  ) => {
    const rows: GeneratedRow[] = [];
    for (let i = 0; i < count; i += 1)
      rows.push(drawGeneratedRow(stratum, stream, seed, first + i));
    return rows;
  };
  const s1 = new DrawStream(A04_SEEDS.C1);
  const s2 = new DrawStream(A04_SEEDS.C2);
  const s3 = new DrawStream(A04_SEEDS.C3);
  const s59 = new DrawStream(A04_SEEDS.C5C9);
  const c1 = draw('C1', s1, A04_SEEDS.C1, GENERATED_COUNTS.C1, 0);
  const c2 = draw('C2', s2, A04_SEEDS.C2, GENERATED_COUNTS.C2, 0);
  const c3 = draw('C3', s3, A04_SEEDS.C3, GENERATED_COUNTS.C3, 0);
  const c5 = draw('C5', s59, A04_SEEDS.C5C9, GENERATED_COUNTS.C5, 0);
  const c9 = draw('C9', s59, A04_SEEDS.C5C9, GENERATED_COUNTS.C9, GENERATED_COUNTS.C5);
  return { rows: { C1: c1, C2: c2, C3: c3, C5: c5, C9: c9 }, streams: [s1, s2, s3, s59] };
}

/** One generated row at one pair: the rescaled path and the per-case paint (13.5). */
export function generatedCaseGeometry(
  row: GeneratedRow,
  zoom: number,
  dpr: number,
): { path: Contour[]; paint: Paint; extent: number } {
  const l = transformMatrix(row.transform);
  const current = physicalExtent(pathPoints(row.path), l, zoom, dpr);
  const k = row.b - floorLog2(current);
  const path = mapPath(row.path, ([x, y]) => [scaleBy(x, k), scaleBy(y, k)]);
  const extent = physicalExtent(pathPoints(path), l, zoom, dpr);
  if (!(extent >= pow2(row.b) && extent < pow2(row.b + 1)))
    throw new Error(`extent ${extent} outside class b=${row.b}`);
  let paint: Paint;
  if (row.fill !== null) paint = { kind: 'fill', rule: row.fill };
  else {
    const wPhys = pow2(-6 + row.widthExponent!);
    const width = (wPhys / dpr / zoom) * pow2(-widthExponent(row.transform));
    paint = stroke(width, row.cap!, row.join!, row.miterLimit!);
  }
  return { path, paint, extent };
}

// ---------------------------------------------------------------------------------------------
// E3-C6, E3-C7, E3-C8 picks (13.4) and the C7 construction (13.6).

const C6_ROWS = [
  's01-I',
  's04-I',
  's08-I',
  's18-I',
  'c01',
  'c02',
  'c16',
  'c11',
  'l04',
  'l32',
  'l44',
  'l66',
];
const C7_ROWS = [
  'c01',
  'c02',
  'c03',
  'c04',
  'c06',
  'c08',
  'c14',
  'c16',
  'k03',
  'k05',
  'k07',
  'k26',
];

export type EdgeScale = Readonly<{ e0: number; s: number; exact: boolean }>;

/** E3-N1: `e₀` and `s = RD(2^(−3−e₀)/(d·z))` exactly. */
export function edgeScale(zoom: number, dpr: number): EdgeScale {
  const dz = dMul(dyadic(dpr), dyadic(zoom));
  // Largest e0 with 2^e0·dz ≤ 2^-3.
  let e0 = -3 - dFloorLog2(dz);
  while (dCmp(dMul(dPow2(e0), dz), dPow2(-3)) > 0) e0 -= 1;
  while (dCmp(dMul(dPow2(e0 + 1), dz), dPow2(-3)) <= 0) e0 += 1;
  // s = 2^(-3-e0) / (n·2^e) = 2^(-3-e0-e) / n.
  const power = -3 - e0 - dz.e;
  const num = power >= 0 ? 1n << BigInt(power) : 1n;
  const den = power >= 0 ? dz.n : dz.n << BigInt(-power);
  const s = roundRational(num, den, 'RD');
  if (!(s >= 1 && s < 2)) throw new Error(`edge scale ${s} outside [1, 2)`);
  const exact = dCmp(dMul(dMul(dPow2(e0), dz), dyadic(s)), dPow2(-3)) === 0;
  return { e0, s, exact };
}

// ---------------------------------------------------------------------------------------------
// The corpus.

export function namedRows(): Readonly<
  Record<'C1' | 'C3' | 'C4' | 'C5' | 'C9', readonly NamedRow[]>
> {
  return { C1: c1Rows(), C3: c3Rows(), C4: c4Rows(), C5: c5Rows(), C9: c9Rows() };
}

/** Every case in generation order (13.2), as canonical objects. */
export function* iterateA04Corpus(): Generator<CanonicalCase, void, undefined> {
  let index = 0;
  const named = namedRows();
  const generated = drawGeneratedRows().rows;
  const emit = (input: CaseInput) => buildCase(input, index++);
  const namedCases = function* (row: NamedRow, transforms: readonly TransformId[]) {
    for (const transform of transforms) {
      const l = transformMatrix(transform);
      for (const [zoom, dpr] of PAIRS) {
        const gap = row.gap === null ? null : c4Gap(row.gap, l, zoom, dpr);
        yield emit({
          stratum: row.stratum,
          row: row.row,
          source: row.source,
          transform,
          l,
          t: [0, 0],
          zoom,
          dpr,
          placement: 'center',
          servedOffset: 0,
          path: row.path({ gLocal: gap === null ? 0 : gap.gLocal }),
          paint: row.paint,
          joint: row.joint,
          opacity: row.opacity,
          sizeClass: null,
          gap,
          duplicateOf: null,
        });
      }
    }
  };
  const generatedCases = function* (rows: readonly GeneratedRow[]) {
    for (const row of rows) {
      const l = transformMatrix(row.transform);
      for (const [zoom, dpr] of PAIRS) {
        const { path, paint } = generatedCaseGeometry(row, zoom, dpr);
        yield emit({
          stratum: row.stratum,
          row: row.row,
          source: row.source,
          transform: row.transform,
          l,
          t: row.t,
          zoom,
          dpr,
          placement: 'center',
          servedOffset: 0,
          path,
          paint,
          joint: null,
          opacity: 1,
          sizeClass: row.sizeClass,
          gap: null,
          duplicateOf: null,
        });
      }
    }
  };
  for (const row of named.C1) yield* namedCases(row, TRANSFORM_IDS);
  yield* generatedCases(generated.C1);
  yield* generatedCases(generated.C2);
  for (const row of named.C3) yield* namedCases(row, TRANSFORM_IDS);
  yield* generatedCases(generated.C3);
  for (const row of named.C4) yield* namedCases(row, TRANSFORM_IDS);
  for (const row of named.C5) yield* namedCases(row, TRANSFORM_IDS);
  yield* generatedCases(generated.C5);
  for (const row of named.C9) yield* namedCases(row, TRANSFORM_IDS);
  yield* generatedCases(generated.C9);
  for (const row of c10Rows()) {
    const l = row.l ?? transformMatrix('T0');
    yield emit({
      stratum: 'C10',
      row: row.row,
      source: row.source,
      transform: 'T0',
      l,
      t: row.placement === 'far' ? [0, 0] : row.t,
      zoom: 1,
      dpr: 1,
      placement: row.placement,
      servedOffset: 0,
      path: row.path({ gLocal: 0 }),
      paint: row.paint,
      joint: null,
      opacity: 1,
      sizeClass: null,
      gap: null,
      duplicateOf: null,
    });
  }
  for (const row of c11Rows()) yield* namedCases(row, TRANSFORM_IDS);
  for (const row of c12Rows()) yield* namedCases(row, ['T2', 'T6']);
  const byId = new Map<string, NamedRow>();
  for (const rows of [named.C1, named.C3, named.C5, named.C9])
    for (const row of rows) byId.set(row.row, row);
  const pick = (id: string) => {
    const row = byId.get(id);
    if (row === undefined) throw new Error(`unknown row ${id}`);
    return row;
  };
  const t0 = transformMatrix('T0');
  const copy = (
    row: NamedRow,
    stratum: Stratum,
    zoom: number,
    dpr: number,
    placement: Placement,
    servedOffset: number,
    transform: TransformId | 'edge',
    l: Matrix,
    duplicateOf: string | null,
  ): CaseInput => ({
    stratum,
    row: row.row,
    source: row.source,
    transform,
    l,
    t: [0, 0],
    zoom,
    dpr,
    placement,
    servedOffset,
    path: row.path({ gLocal: 0 }),
    paint: row.paint,
    // A C6, C7 or C8 copy has no partner paint, so it carries no joint group (review round 1).
    joint: null,
    opacity: row.opacity,
    sizeClass: null,
    gap: null,
    duplicateOf,
  });
  for (const id of C6_ROWS)
    for (const placement of ['partial', 'far', 'pan'] as const)
      for (const [zoom, dpr] of PAIRS)
        yield emit(copy(pick(id), 'C6', zoom, dpr, placement, 0, 'T0', t0, null));
  for (const id of C7_ROWS) {
    const row = pick(id);
    for (const [zoom, dpr] of PAIRS) {
      const edge = edgeScale(zoom, dpr);
      const duplicateOf =
        edge.s === 1 ? caseId(row.stratum, row.row, 'T0', zoom, dpr, 'center', 0) : null;
      yield emit(
        copy(row, 'C7', zoom, dpr, 'center', 0, 'edge', [edge.s, 0, 0, edge.s], duplicateOf),
      );
    }
  }
  for (const row of [...named.C1, ...named.C3, ...named.C5])
    for (const offset of [1, 2])
      for (const [zoom, dpr] of PAIRS)
        yield emit(copy(row, 'C8', zoom, dpr, 'center', offset, 'T0', t0, null));
}

export type CorpusSummary = Readonly<{
  cases: number;
  corpusSha256: string;
  counts: Readonly<Record<string, number>>;
  bytes: number;
}>;

/** Generates the corpus and returns its SHA-256 over the canonical UTF-8 text (5.1). */
export function summarizeA04Corpus(
  visit?: (value: CanonicalCase, line: string) => void,
): CorpusSummary {
  const hash = createHash('sha256');
  const counts: Record<string, number> = {};
  let cases = 0;
  let bytes = 0;
  for (const value of iterateA04Corpus()) {
    const line = `${serializeCase(value)}\n`;
    hash.update(line, 'utf8');
    bytes += Buffer.byteLength(line, 'utf8');
    const stratum = value.stratum as string;
    counts[stratum] = (counts[stratum] ?? 0) + 1;
    cases += 1;
    visit?.(value, line);
  }
  return { cases, corpusSha256: hash.digest('hex'), counts, bytes };
}
